import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { flushPromises, mount, type VueWrapper } from '@vue/test-utils';
import { nextTick } from 'vue';
import ReaderView from '../src/components/ReaderView.vue';
import type { Conversation, ConversationRef, MailError } from '../src/lib/ipc/client';

const ACCOUNT_A = 'account-a';
const ACCOUNT_B = 'account-b';

function refOf(accountId: string, conversationId: string): ConversationRef {
  return { accountId, conversationId };
}

function message(
  id: string,
  bodyText = `Body of ${id}.`,
  from = { displayName: 'Ada Fixture', mailbox: 'ada@example.test' },
) {
  return {
    id,
    from,
    to: [{ displayName: 'You', mailbox: 'you@example.test' }],
    sentAt: '2026-02-02T09:00:00Z',
    bodyText,
  };
}

function conversationOf(accountId: string, messageIds: string[], extra: Partial<Conversation> = {}): Conversation {
  return {
    ref: refOf(accountId, 'read-01'),
    subject: 'Reader journey thread',
    messages: messageIds.map((id) => message(id)),
    isInInbox: true,
    pendingOperationId: null,
    ...extra,
  };
}

const NOT_FOUND: MailError = { kind: 'not_found' };

function mountReader(conversation: Conversation, state: 'ready' | 'loading' | 'error' = 'ready') {
  return mount(ReaderView, {
    props: {
      conversation: state === 'ready' ? conversation : null,
      state,
      error: null,
      commandInFlight: false,
      openRef: conversation.ref,
    },
    attachTo: document.body,
  });
}

function toggleFor(wrapper: VueWrapper, messageId: string) {
  return wrapper.find(`[data-test="message-toggle-${messageId}"]`);
}

async function settle(wrapper: VueWrapper): Promise<void> {
  await flushPromises();
  await nextTick();
  await flushPromises();
  void wrapper;
}

describe('ReaderView visit-scoped message state (UX-02)', () => {
  let wrapper: VueWrapper | null = null;

  afterEach(() => {
    wrapper?.unmount();
    wrapper = null;
  });

  it.each([
    [{ starredMessages: 1, knownMessages: 3, totalMessages: 3 }, 'Starred'],
    [{ starredMessages: 1, knownMessages: 2, totalMessages: 3 }, 'Starred (partial)'],
    [{ starredMessages: 0, knownMessages: 1, totalMessages: 3 }, 'Star state unknown'],
  ])('keeps the star line short and moves coverage into the title and description (%j)', async (stars, visible) => {
    wrapper = mountReader(conversationOf(ACCOUNT_A, ['read-m1'], { stars }));
    await settle(wrapper!);
    const line = wrapper!.get('[data-test="reader-stars"]');
    const time = first.find('time.message-time');
    expect(time.attributes('datetime')).toBe('2026-02-02T09:00:00.000Z');
    expect(time.attributes('title')).toMatch(/^Mon 2 Feb 2026, \d+:\d{2} [AP]M$/);
    expect(time.find('[aria-hidden="true"]').text()).toMatch(/^(\d+ Feb( 2026)?|\d+:\d{2} [AP]M)$/);
    expect(first.text()).toContain(time.attributes('title'));
    // An empty body shows no snippet rather than invented text.
    expect(toggleFor(wrapper!, 'read-m2').find('.message-snippet').exists()).toBe(false);
    await first.trigger('click');
    await settle(wrapper!);
    expect(toggleFor(wrapper!, 'read-m1').attributes('aria-expanded')).toBe('true');
    expect(toggleFor(wrapper!, 'read-m1').find('.message-snippet').exists()).toBe(false);
    expect(toggleFor(wrapper!, 'read-m1').find('time.message-time').exists()).toBe(true);
  });

  it('updates message identity when any message control receives focus', async () => {
    const conversation = conversationOf(ACCOUNT_A, ['read-m1', 'read-m2', 'read-m3']);
    wrapper = mountReader(conversation);
    await settle(wrapper!);
    (toggleFor(wrapper!, 'read-m1').element as HTMLElement).focus();
